import base64,hashlib,json,yaml
def approval(run,case):
    args=['helm','upgrade','--install',case['release'],str(case['chart']),'--dry-run=server','--disable-openapi-validation','--output','json','--kubeconfig',str(case['kubeconfig']),'--namespace',case['namespace']]
    code,out,error=run(args)
    if code:raise RuntimeError('server-connected approval render failed')
    release=json.loads(out)
    matches=[doc for doc in yaml.safe_load_all(release['manifest']) if doc and doc.get('kind')=='Secret' and doc.get('metadata',{}).get('name')==case['secret_name']]
    if len(matches)!=1:raise ValueError('one intended Secret manifest required')
    secret=matches[0];payload=base64.b64decode(secret['data']['token'],validate=True)
    return {'namespace':secret['metadata']['namespace'],'name':secret['metadata']['name'],'token_sha256':hashlib.sha256(payload).hexdigest()}

